// #6a993d794918a5e83bc3231b (#c3231b) AC4 — менеджер заблокированного бизнеса: вход отклонён, сообщение и «פנייה לתמיכה» (кейс AUTH-LG-007).
// spec: specs/auth-login.md (4.1) · seed: tests/seed.spec.ts.
// Данные: бизнес QA-A Block 0410 (b93165ca-…) заблокирован и оставлен «לחסימה»; его менеджер — сессия .qa/auth/blockmgr.json
// (тот же аккаунт, что в tests/user-access/blocked-business-token.spec.ts).
// Без пароля: сессия обновляется по refresh_token и записывается обратно в blockmgr.json (support/session.ts),
// затем открывается приложение. Выход, который приложение делает при блокировке, ПОДМЕНЁН (204), чтобы
// сессия blockmgr на сервере не отзывалась и соседний тест продолжал работать.
// Вариант «ввод верного пароля» и заблокированный лично пользователь — ручные (AUTH-LG-007).
import * as path from 'path';
import { test, expect } from '../../fixtures';
import { openWithApi } from '../support/api';
import { refreshSession, authFile } from '../support/session';
import { mockAuth, LOGOUT } from '../support/auth-mocks';

const BLOCKED_BUSINESS_ID = 'b93165ca-b5cb-4292-ae5b-c0278e39fc6f';

test.describe('Вход — заблокированный бизнес (#6a993d794918a5e83bc3231b)', () => {
  test('blockmgr (бизнес заблокирован): «/» → /login?notice=blocked, экран «הכניסה לחשבון חסומה» без формы, ссылка «פנייה לתמיכה» @desktop #6a993d794918a5e83bc3231b #af074d', async ({ asUser, browser }) => {
    // Предусловие: бизнес действительно заблокирован (иначе падение — окружение, не баг).
    const admin = await asUser('admin');
    const adminApi = await openWithApi(admin, `/admin/businesses/${BLOCKED_BUSINESS_ID}`);
    await expect(admin.getByRole('region', { name: 'סטטוס החשבון' })).toContainText('חסום');

    // Свежая сессия blockmgr (записана в файл) → окно с этой сессией.
    await refreshSession(admin.request, adminApi.headers.apikey, 'blockmgr');
    const ctx = await browser.newContext({
      baseURL: test.info().project.use.baseURL,
      locale: 'he-IL',
      viewport: { width: 1440, height: 900 },
      storageState: authFile('blockmgr'),
    });
    try {
      const page = await ctx.newPage();
      const logout = await mockAuth(page, LOGOUT, { status: 204 });

      await page.goto('/');
      // AC4 «ההתחברות נדחית והוא מופנה לפנייה לתמיכה»; FL-05 «הודעה נפרדת עם נתיב פנייה לתמיכה».
      await page.waitForURL((u) => u.pathname === '/login' && u.searchParams.get('notice') === 'blocked');
      const notice = page.getByTestId('account-blocked');
      await expect(notice).toBeVisible();
      // Переход по сохранённой сессии (без ввода пароля) — причина неизвестна экрану: общий текст «unknown».
      await expect(notice).toHaveAttribute('data-reason', 'unknown');
      // С #af074d (04.11.2026): отдельный экран Figma 721:1083 без формы входа, общий текст кадра.
      await expect(notice).toContainText('הכניסה לחשבון חסומה');
      await expect(notice).toContainText('החשבון שלכם או החשבון של העסק חסום כרגע, ולכן לא ניתן להיכנס.');
      await expect(page.getByTestId('blocked-support')).toContainText('צוות התמיכה');
      await expect(page.getByRole('textbox')).toHaveCount(0);
      await expect(page.getByRole('button', { name: 'כניסה', exact: true })).toHaveCount(0);
      await expect(page.getByRole('link', { name: 'פנייה לתמיכה' })).toHaveAttribute('href', /^mailto:simulator@shnaider\.pro/);

      // Кабинет не открыт, локальная сессия удалена; выход запрошен только локально.
      await expect(page.getByRole('button', { name: 'התנתקות' })).toHaveCount(0);
      expect(logout.calls.every((u) => !/scope=global/.test(u)), 'при блокировке — выход scope=local').toBe(true);
      expect(await page.evaluate(() => Object.keys(localStorage).filter((k) => /^sb-.+-auth-token$/.test(k)))).toEqual([]);
    } finally {
      await ctx.close();
    }
  });
});
